function normalizeBodies(messageIds, responses) {
  if (!Array.isArray(messageIds) || !Array.isArray(responses) || messageIds.length !== responses.length) throw new Error('Gmail body count differs from the incoming message count.');
  const messages = messageIds.map((messageId, index) => {
    const response = responses[index];
    if (response?.messageId !== messageId || typeof response.body !== 'string') throw new Error('Gmail returned a different message ID or invalid body.');
    return { messageId, body: response.body };
  });
  return { messages };
}

const incoming=$('Gmail trigger').all().map(item=>({messageId:item.json.id}));
const prepareEvents = function prepareMessages({ events }) {
  if (!Array.isArray(events) || events.length > 25) throw new Error('Expected at most 25 incoming Gmail events.');
  const messageIds = [], seen = new Set();
  for (const event of events) {
    const id = event?.messageId;
    if (typeof id !== 'string' || !id.trim() || seen.has(id)) throw new Error('Incoming Gmail message IDs must be nonempty and unique.');
    seen.add(id); messageIds.push(id);
  }
  return { messageIds, count: messageIds.length };
}

