const prepare = function prepareLabelWrites({ classifications, labels }) {
  if (!Array.isArray(classifications) || classifications.length > 25 || !Array.isArray(labels)) throw new Error('Invalid Gmail label plan.');
  const catalog = new Map(), allowed = ['Inquiry', 'Partnership', 'Notification'];
  for (const label of labels) {
    if (!allowed.includes(label?.name)) continue;
    if (typeof label.id !== 'string' || !label.id.trim() || catalog.has(label.name)) throw new Error('Configured Gmail label names must have one valid ID each.');
    catalog.set(label.name, label.id);
  }
  const seen = new Set(), plans = classifications.map(classification => {
    if (typeof classification?.messageId !== 'string' || !classification.messageId.trim() || seen.has(classification.messageId) || !Array.isArray(classification.labels)) throw new Error('Classifications must keep unique incoming Gmail message IDs.');
    seen.add(classification.messageId);
    const names = [], ids = [];
    for (const name of classification.labels) {
      if (!allowed.includes(name) || !catalog.has(name)) throw new Error('A selected label is unknown or missing from the connected Gmail account.');
      if (!names.includes(name)) { names.push(name); ids.push(catalog.get(name)); }
    }
    return { messageId: classification.messageId, labels: names, labelIds: ids };
  });
  return { plans };
}

